using System.Data;
using DigitalAgriculturalMarketPlace.Data;
using DigitalAgriculturalMarketplace.Models;
using DigitalAgriculturalMarketplace.ViewModels;
using Microsoft.EntityFrameworkCore;

namespace DigitalAgriculturalMarketplace.Services;
public class RfqWorkflowService
{
    private readonly ApplicationDbContext _db;
    private readonly InventoryService _inventory;
    public RfqWorkflowService(ApplicationDbContext db,InventoryService inventory){_db=db;_inventory=inventory;}

    public async Task<WorkflowResult> CreateAsync(int buyerId,RfqCreateViewModel model)
    {
        var items=model.Items.Where(x=>x.CatalogProductId>0&&x.UnitOfMeasureId>0&&x.RequestedQuantity>0).ToList();
        if(items.Count==0)return WorkflowResult.Fail("Add at least one valid RFQ item.");
        if(items.GroupBy(x=>new{x.CatalogProductId,x.UnitOfMeasureId}).Any(g=>g.Count()>1))return WorkflowResult.Fail("Each product and unit combination may appear only once.");
        var catalogIds=items.Select(x=>x.CatalogProductId).Distinct().ToList(); var unitIds=items.Select(x=>x.UnitOfMeasureId).Distinct().ToList();
        if(await _db.CatalogProducts.CountAsync(x=>catalogIds.Contains(x.Id)&&x.Status=="Approved"&&x.IsActive)!=catalogIds.Count)return WorkflowResult.Fail("Every RFQ item must use an approved catalog product.");
        if(await _db.UnitsOfMeasure.CountAsync(x=>unitIds.Contains(x.Id)&&x.IsActive)!=unitIds.Count)return WorkflowResult.Fail("Every RFQ item must use an active explicit unit.");
        var units=await _db.UnitsOfMeasure.Where(x=>unitIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id);
        foreach(var x in items)if(!QuantityRules.IsValid(x.RequestedQuantity,units[x.UnitOfMeasureId].DecimalPlaces))return WorkflowResult.Fail(QuantityRules.Message(units[x.UnitOfMeasureId].Code,units[x.UnitOfMeasureId].DecimalPlaces));
        var now=DateTime.UtcNow; var rfq=new Rfq{BuyerId=buyerId,Title=model.Title.Trim(),Description=model.Description?.Trim(),DeliveryLocation=model.DeliveryLocation.Trim(),RequiredByDate=model.RequiredByDate,Status="Draft",CreatedAt=now};
        foreach(var x in items)rfq.Items.Add(new RfqItem{CatalogProductId=x.CatalogProductId,UnitOfMeasureId=x.UnitOfMeasureId,RequestedQuantity=x.RequestedQuantity,AcceptedQuantity=0,MaximumBudgetPerUnit=x.MaximumBudgetPerUnit,Specifications=x.Specifications?.Trim()});
        _db.Rfqs.Add(rfq);await _db.SaveChangesAsync();rfq.RfqNumber=$"RFQ-{now:yyyyMMdd}-{rfq.Id:D6}";await _db.SaveChangesAsync();return WorkflowResult.Ok("RFQ draft created.",rfq.Id);
    }
    public async Task<WorkflowResult> PublishAsync(int id,int buyerId)
    {var rfq=await _db.Rfqs.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id&&x.BuyerId==buyerId);if(rfq is null)return WorkflowResult.Fail("RFQ not found.");if(rfq.Status!="Draft")return WorkflowResult.Fail("Only draft RFQs can be published.");if(rfq.RequiredByDate.Date<DateTime.UtcNow.Date)return WorkflowResult.Fail("Required-by date must not be in the past.");rfq.Status="Open";rfq.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();return WorkflowResult.Ok("RFQ published.",id);}
    public async Task<WorkflowResult> CloseAsync(int id,int buyerId)
    {var rfq=await _db.Rfqs.FirstOrDefaultAsync(x=>x.Id==id&&x.BuyerId==buyerId);if(rfq is null)return WorkflowResult.Fail("RFQ not found.");if(rfq.Status is not ("Open" or "PartiallyFulfilled"))return WorkflowResult.Fail("Only open RFQs can be closed.");rfq.Status="Closed";rfq.ClosedAt=DateTime.UtcNow;rfq.UpdatedAt=DateTime.UtcNow;AddNotification(buyerId,"RFQ closed",$"{rfq.RfqNumber} has been closed.","RFQ",rfq.Id,$"notify:rfq-closed:{rfq.Id}");await _db.SaveChangesAsync();return WorkflowResult.Ok("RFQ closed.",id);}

    public async Task<WorkflowResult> UpdateDraftAsync(int buyerId,RfqCreateViewModel model)
    {
        var rfq=await _db.Rfqs.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==model.Id&&x.BuyerId==buyerId);if(rfq is null)return WorkflowResult.Fail("RFQ not found.");if(rfq.Status!="Draft")return WorkflowResult.Fail("Only draft RFQs can be edited.");
        var items=model.Items.Where(x=>x.CatalogProductId>0&&x.UnitOfMeasureId>0&&x.RequestedQuantity>0).ToList();if(items.Count==0)return WorkflowResult.Fail("Add at least one valid RFQ item.");if(items.GroupBy(x=>new{x.CatalogProductId,x.UnitOfMeasureId}).Any(g=>g.Count()>1))return WorkflowResult.Fail("Each product and unit combination may appear only once.");
        var cids=items.Select(x=>x.CatalogProductId).Distinct().ToList();var uids=items.Select(x=>x.UnitOfMeasureId).Distinct().ToList();if(await _db.CatalogProducts.CountAsync(x=>cids.Contains(x.Id)&&x.Status=="Approved"&&x.IsActive)!=cids.Count||await _db.UnitsOfMeasure.CountAsync(x=>uids.Contains(x.Id)&&x.IsActive)!=uids.Count)return WorkflowResult.Fail("Every item requires an approved product and active unit.");
        var units=await _db.UnitsOfMeasure.Where(x=>uids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id);foreach(var x in items)if(!QuantityRules.IsValid(x.RequestedQuantity,units[x.UnitOfMeasureId].DecimalPlaces))return WorkflowResult.Fail(QuantityRules.Message(units[x.UnitOfMeasureId].Code,units[x.UnitOfMeasureId].DecimalPlaces));
        rfq.Title=model.Title.Trim();rfq.Description=model.Description?.Trim();rfq.DeliveryLocation=model.DeliveryLocation.Trim();rfq.RequiredByDate=model.RequiredByDate;rfq.UpdatedAt=DateTime.UtcNow;_db.RfqItems.RemoveRange(rfq.Items);foreach(var x in items)rfq.Items.Add(new(){CatalogProductId=x.CatalogProductId,UnitOfMeasureId=x.UnitOfMeasureId,RequestedQuantity=x.RequestedQuantity,MaximumBudgetPerUnit=x.MaximumBudgetPerUnit,Specifications=x.Specifications?.Trim()});await _db.SaveChangesAsync();return WorkflowResult.Ok("RFQ draft updated.",rfq.Id);
    }

    public async Task<WorkflowResult> SubmitQuotationAsync(int sellerId,QuotationCreateViewModel model,bool submit=true)
    {
        var rfq=await _db.Rfqs.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==model.RfqId);if(rfq is null||rfq.Status!="Open")return WorkflowResult.Fail("RFQ is not open.");if(rfq.BuyerId==sellerId)return WorkflowResult.Fail("You cannot quote on your own RFQ.");
        if(!await _db.SellerProfiles.AnyAsync(x=>x.UserId==sellerId&&x.IsActive))return WorkflowResult.Fail("Activate your seller profile before quoting.");
        if(await _db.Quotations.AnyAsync(x=>x.RfqId==rfq.Id&&x.SellerId==sellerId))return WorkflowResult.Fail("You already have a quotation for this RFQ.");
        var inputs=model.Items.Where(x=>x.OfferedQuantity>0).ToList();if(inputs.Count==0)return WorkflowResult.Fail("Quote at least one RFQ item.");
        var products=await _db.Products.Include(x=>x.CatalogProduct).Include(x=>x.UnitOfMeasure).Where(x=>x.FarmerId==sellerId).ToDictionaryAsync(x=>x.Id);
        foreach(var input in inputs){var ri=rfq.Items.SingleOrDefault(x=>x.Id==input.RfqItemId);if(ri is null||!products.TryGetValue(input.ProductId,out var p)||!p.IsActive||p.CatalogProductId!=ri.CatalogProductId||p.UnitOfMeasureId!=ri.UnitOfMeasureId||p.CatalogProduct?.Status!="Approved"||!p.CatalogProduct.IsActive||p.UnitOfMeasure is null||!p.UnitOfMeasure.IsActive)return WorkflowResult.Fail("A quoted listing is not eligible or does not match the RFQ item.");if(!QuantityRules.IsValid(input.OfferedQuantity,p.UnitOfMeasure.DecimalPlaces))return WorkflowResult.Fail(QuantityRules.Message(p.UnitOfMeasure.Code,p.UnitOfMeasure.DecimalPlaces));if(input.OfferedQuantity>ri.RequestedQuantity)return WorkflowResult.Fail("Offered quantity exceeds the requested quantity.");}
        var now=DateTime.UtcNow;var q=new Quotation{RfqId=rfq.Id,SellerId=sellerId,Status=submit?"Submitted":"Draft",Notes=model.Notes?.Trim(),ValidUntil=model.ValidUntil,CreatedAt=now};foreach(var x in inputs)q.Items.Add(new QuotationItem{RfqItemId=x.RfqItemId,ProductId=x.ProductId,OfferedQuantity=x.OfferedQuantity,UnitPrice=x.UnitPrice,EstimatedDeliveryDate=x.EstimatedDeliveryDate,Notes=x.Notes?.Trim()});_db.Quotations.Add(q);await _db.SaveChangesAsync();q.QuotationNumber=$"QUO-{now:yyyyMMdd}-{q.Id:D6}";if(submit)AddNotification(rfq.BuyerId,"New quotation",$"{q.QuotationNumber} was submitted for {rfq.RfqNumber}.","Quotation",q.Id,$"notify:quotation-submitted:{q.Id}");await _db.SaveChangesAsync();return WorkflowResult.Ok(submit?"Quotation submitted.":"Quotation draft saved.",q.Id);
    }
    public async Task<WorkflowResult> WithdrawAsync(int quotationId,int sellerId)
    {var q=await _db.Quotations.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==quotationId&&x.SellerId==sellerId);if(q is null)return WorkflowResult.Fail("Quotation not found.");if(q.Status is not ("Draft" or "Submitted")||q.Items.Any(x=>x.AcceptedQuantity>0))return WorkflowResult.Fail("This quotation can no longer be withdrawn.");q.Status="Withdrawn";q.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();return WorkflowResult.Ok("Quotation withdrawn.",quotationId);}

    public async Task<WorkflowResult> SubmitDraftAsync(int quotationId,int sellerId)
    {var q=await _db.Quotations.Include(x=>x.Rfq).Include(x=>x.Items).ThenInclude(x=>x.Product).ThenInclude(x=>x!.CatalogProduct).Include(x=>x.Items).ThenInclude(x=>x.Product).ThenInclude(x=>x!.UnitOfMeasure).Include(x=>x.Items).ThenInclude(x=>x.RfqItem).FirstOrDefaultAsync(x=>x.Id==quotationId&&x.SellerId==sellerId);if(q is null)return WorkflowResult.Fail("Quotation not found.");if(q.Status!="Draft"||q.Rfq?.Status!="Open")return WorkflowResult.Fail("Only a draft for an open RFQ can be submitted.");if(q.ValidUntil.Date<DateTime.Today)return WorkflowResult.Fail("Quotation validity has expired.");if(!await _db.SellerProfiles.AnyAsync(x=>x.UserId==sellerId&&x.IsActive)||q.Items.Any(i=>i.Product is null||!i.Product.IsActive||i.Product.CatalogProductId!=i.RfqItem!.CatalogProductId||i.Product.UnitOfMeasureId!=i.RfqItem.UnitOfMeasureId||i.Product.CatalogProduct?.Status!="Approved"||!i.Product.CatalogProduct.IsActive||i.Product.UnitOfMeasure is null||!i.Product.UnitOfMeasure.IsActive||!QuantityRules.IsValid(i.OfferedQuantity,i.Product.UnitOfMeasure.DecimalPlaces)))return WorkflowResult.Fail("A listing is no longer eligible or a quantity does not match its unit precision.");q.Status="Submitted";q.UpdatedAt=DateTime.UtcNow;AddNotification(q.Rfq.BuyerId,"New quotation",$"{q.QuotationNumber} was submitted for {q.Rfq.RfqNumber}.","Quotation",q.Id,$"notify:quotation-submitted:{q.Id}");await _db.SaveChangesAsync();return WorkflowResult.Ok("Quotation submitted.",quotationId);}

    public async Task<WorkflowResult> UpdateQuotationDraftAsync(int sellerId,QuotationCreateViewModel model)
    {
        var q=await _db.Quotations.Include(x=>x.Rfq).ThenInclude(x=>x!.Items).Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==model.Id&&x.SellerId==sellerId);if(q is null)return WorkflowResult.Fail("Quotation not found.");if(q.Status!="Draft"||q.Rfq?.Status!="Open")return WorkflowResult.Fail("Only a draft for an open RFQ can be edited.");
        var inputs=model.Items.Where(x=>x.OfferedQuantity>0).ToList();if(inputs.Count==0)return WorkflowResult.Fail("Quote at least one RFQ item.");var products=await _db.Products.Include(x=>x.CatalogProduct).Include(x=>x.UnitOfMeasure).Where(x=>x.FarmerId==sellerId).ToDictionaryAsync(x=>x.Id);
        foreach(var input in inputs){var ri=q.Rfq.Items.SingleOrDefault(x=>x.Id==input.RfqItemId);if(ri is null||!products.TryGetValue(input.ProductId,out var p)||!p.IsActive||p.CatalogProductId!=ri.CatalogProductId||p.UnitOfMeasureId!=ri.UnitOfMeasureId||p.CatalogProduct?.Status!="Approved"||!p.CatalogProduct.IsActive||p.UnitOfMeasure is null||!p.UnitOfMeasure.IsActive)return WorkflowResult.Fail("A quoted listing is not eligible or does not match the RFQ item.");if(!QuantityRules.IsValid(input.OfferedQuantity,p.UnitOfMeasure.DecimalPlaces))return WorkflowResult.Fail(QuantityRules.Message(p.UnitOfMeasure.Code,p.UnitOfMeasure.DecimalPlaces));if(input.OfferedQuantity>ri.RequestedQuantity)return WorkflowResult.Fail("Offered quantity exceeds the requested quantity.");}
        _db.QuotationItems.RemoveRange(q.Items);q.Notes=model.Notes?.Trim();q.ValidUntil=model.ValidUntil;q.UpdatedAt=DateTime.UtcNow;foreach(var x in inputs)q.Items.Add(new(){RfqItemId=x.RfqItemId,ProductId=x.ProductId,OfferedQuantity=x.OfferedQuantity,UnitPrice=x.UnitPrice,EstimatedDeliveryDate=x.EstimatedDeliveryDate,Notes=x.Notes?.Trim()});await _db.SaveChangesAsync();return WorkflowResult.Ok("Quotation draft updated.",q.Id);
    }

    public async Task<WorkflowResult> AcceptAsync(int buyerId,AllocationViewModel model)
    {
        if(model.Quantity<=0)return WorkflowResult.Fail("Accepted quantity must be positive.");
        await using var tx=await _db.Database.BeginTransactionAsync(IsolationLevel.Serializable);
        var duplicate=await _db.QuotationAllocations.FirstOrDefaultAsync(x=>x.OperationKey==model.OperationKey);if(duplicate is not null)return WorkflowResult.Ok("This allocation was already processed.",duplicate.OrderId);
        var qi=await _db.QuotationItems.Include(x=>x.Quotation)!.ThenInclude(x=>x!.Rfq).Include(x=>x.RfqItem).Include(x=>x.Product)!.ThenInclude(x=>x!.CatalogProduct).Include(x=>x.Product)!.ThenInclude(x=>x!.UnitOfMeasure).FirstOrDefaultAsync(x=>x.Id==model.QuotationItemId);
        if(qi?.Quotation?.Rfq is null||qi.RfqItem is null||qi.Product is null)return WorkflowResult.Fail("Quotation item not found.");var q=qi.Quotation;var rfq=q.Rfq;var p=qi.Product;
        await _db.Entry(q).Collection(x=>x.Items).LoadAsync();await _db.Entry(rfq).Collection(x=>x.Items).LoadAsync();
        if(rfq.BuyerId!=buyerId)return WorkflowResult.Fail("You do not own this RFQ.");if(rfq.Status is not ("Open" or "PartiallyFulfilled"))return WorkflowResult.Fail("RFQ cannot accept allocations.");if(q.Status is not ("Submitted" or "PartiallyAccepted"))return WorkflowResult.Fail("Quotation cannot be accepted.");if(q.ValidUntil.Date<DateTime.Today){q.Status="Expired";q.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();await tx.CommitAsync();return WorkflowResult.Fail("Quotation has expired.");}
        if(!p.IsActive||p.FarmerId!=q.SellerId||p.CatalogProductId!=qi.RfqItem.CatalogProductId||p.UnitOfMeasureId!=qi.RfqItem.UnitOfMeasureId||p.CatalogProduct?.Status!="Approved"||!p.CatalogProduct.IsActive||p.UnitOfMeasure is null||!p.UnitOfMeasure.IsActive||!await _db.SellerProfiles.AnyAsync(x=>x.UserId==q.SellerId&&x.IsActive))return WorkflowResult.Fail("Seller listing is no longer eligible.");
        if(!QuantityRules.IsValid(model.Quantity,p.UnitOfMeasure.DecimalPlaces))return WorkflowResult.Fail(QuantityRules.Message(p.UnitOfMeasure.Code,p.UnitOfMeasure.DecimalPlaces));
        if(qi.AcceptedQuantity+model.Quantity>qi.OfferedQuantity)return WorkflowResult.Fail("Acceptance exceeds the offered quantity.");if(qi.RfqItem.AcceptedQuantity+model.Quantity>qi.RfqItem.RequestedQuantity)return WorkflowResult.Fail("Acceptance exceeds the RFQ remaining quantity.");var available=p.AvailableQuantity??p.Quantity;if(model.Quantity>available)return WorkflowResult.Fail("Seller has insufficient available inventory.");
        var now=DateTime.UtcNow;var total=decimal.Round(model.Quantity*qi.UnitPrice,2);var order=new Order{ConsumerId=buyerId,ProductId=p.Id,SellerId=q.SellerId,Quantity=model.Quantity,TotalPrice=total,Subtotal=total,Status="Pending",OrderDate=now,UpdatedAt=now};_db.Orders.Add(order);await _db.SaveChangesAsync();order.OrderNumber=$"AG-RFQ-{now:yyyyMMdd}-{order.Id:D6}";
        var item=new OrderItem{OrderId=order.Id,ProductId=p.Id,ProductNameSnapshot=p.Name,UnitNameSnapshot=p.UnitOfMeasure.Name,Quantity=model.Quantity,UnitPrice=qi.UnitPrice,LineTotal=total,SellerId=q.SellerId};_db.OrderItems.Add(item);await _db.SaveChangesAsync();
        p.AvailableQuantity=available-model.Quantity;p.ReservedQuantity+=model.Quantity;InventoryService.SyncLegacyQuantity(p);_db.InventoryReservations.Add(new InventoryReservation{ProductId=p.Id,OrderItemId=item.Id,Quantity=model.Quantity,Status="Active",ReservedAt=now,OperationKey=$"rfq:reserve:{model.OperationKey}"});_inventory.AddMovement(p,"ReservationCreated",-model.Quantity,model.Quantity,buyerId,"RfqAllocation",qi.Id,null,$"rfq:movement:{model.OperationKey}");_db.OrderStatusHistory.Add(new OrderStatusHistory{OrderId=order.Id,ToStatus="Pending",ChangedByUserId=buyerId,Reason=$"Accepted from quotation {q.QuotationNumber}",ChangedAt=now,OperationKey=$"rfq:status:{model.OperationKey}"});
        var allocation=new QuotationAllocation{QuotationItemId=qi.Id,RfqItemId=qi.RfqItemId,BuyerId=buyerId,SellerId=q.SellerId,OrderId=order.Id,AcceptedQuantity=model.Quantity,AcceptedUnitPrice=qi.UnitPrice,CreatedAt=now,OperationKey=model.OperationKey};_db.QuotationAllocations.Add(allocation);qi.AcceptedQuantity+=model.Quantity;qi.RfqItem.AcceptedQuantity+=model.Quantity;
        q.Status=q.Items.All(x=>x.Id==qi.Id?x.AcceptedQuantity>=x.OfferedQuantity:x.AcceptedQuantity>=x.OfferedQuantity)?"Accepted":"PartiallyAccepted";rfq.Status=rfq.Items.All(x=>x.Id==qi.RfqItemId?x.AcceptedQuantity>=x.RequestedQuantity:x.AcceptedQuantity>=x.RequestedQuantity)?"Fulfilled":"PartiallyFulfilled";q.UpdatedAt=now;rfq.UpdatedAt=now;
        AddNotification(q.SellerId,q.Status=="Accepted"?"Quotation accepted":"Quotation partially accepted",$"The buyer accepted {model.Quantity:0.###} {p.UnitOfMeasure.Code} from {q.QuotationNumber}.","Quotation",q.Id,$"notify:quotation-allocation:{model.OperationKey}");
        AddNotification(q.SellerId,"New seller order",$"Order {order.OrderNumber} was created from the accepted quotation.","Order",order.Id,$"notify:rfq-order:{model.OperationKey}");
        if(rfq.Status=="Fulfilled")AddNotification(buyerId,"RFQ fulfilled",$"{rfq.RfqNumber} is fully allocated.","RFQ",rfq.Id,$"notify:rfq-fulfilled:{rfq.Id}");
        try{await _db.SaveChangesAsync();await tx.CommitAsync();return WorkflowResult.Ok("Allocation accepted and seller order created.",order.Id);}catch(DbUpdateException){return WorkflowResult.Fail("The allocation conflicted with another request. Refresh and try again.");}
    }

    private void AddNotification(int userId,string title,string message,string type,int relatedId,string operationKey)
    {if(!_db.Notifications.Local.Any(n=>n.OperationKey==operationKey))_db.Notifications.Add(new Notification{UserId=userId,Title=title,Message=message,Type=type,RelatedId=relatedId,OperationKey=operationKey,CreatedAt=DateTime.UtcNow});}
}
